import { readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const scriptDirectory = dirname(fileURLToPath(import.meta.url));
const toolRoot = resolve(scriptDirectory, "..");
const generatedFile = resolve(
  toolRoot,
  "src",
  "framework-versions.generated.ts",
);
const checkOnly = process.argv.includes("--check");

const entries = [
  ["elfui", "^0.1.0-beta.0"],
  ["vitePlugin", "^0.1.0-beta.0"],
  ["router", "^0.1.0-beta.0"],
  ["chain", "^0.1.0-beta.0"],
];

const source = [
  "// Generated by scripts/sync-framework-versions.mjs. Do not edit manually.",
  "",
  "export interface FrameworkDependencyVersions {",
  ...entries.map(([key]) => `  ${key}: string;`),
  "}",
  "",
  "export const frameworkDependencyVersions: FrameworkDependencyVersions = {",
  ...entries.map(
    ([key, version], index) =>
      `  ${key}: "${version}"${index === entries.length - 1 ? "" : ","}`,
  ),
  "};",
  "",
].join("\n");

let currentSource = "";
try {
  currentSource = await readFile(generatedFile, "utf8");
} catch (error) {
  if (error?.code !== "ENOENT") throw error;
}

if (checkOnly) {
  if (currentSource !== source) {
    throw new Error(
      "Framework package versions changed. Run pnpm sync:versions.",
    );
  }
} else if (currentSource !== source) {
  await writeFile(generatedFile, source, "utf8");
}
